// pb-ssh-response (C9 v0): everything this execution needs. Called by
// recv-thehive-event for an alert update whose tags newly include lib-config
// response.approval.tag (the interim approval, until D-N5's approval task).
const input = $input.first().json;
if (!input.config || !input.config.response || !input.config.writeback) throw new Error(`${$workflow.name} needs the lib-config output as \`config\``);
const e = input.event !== null && typeof input.event === 'object' ? input.event : {};
if (typeof e.thehive_alert_id !== 'string' || e.thehive_alert_id === '') throw new Error(`${$workflow.name} needs event.thehive_alert_id`);
return [{ json: {
  config: input.config,
  event: {
    thehive_alert_id: e.thehive_alert_id,
    actor: typeof e.actor === 'string' ? e.actor : null,
    // The audit record's top-level _createdAt (C4): the approval's own time.
    event_time_ms: Number.isFinite(e.event_time_ms) ? e.event_time_ms : null,
    request_id: e.request_id ?? null,
    how: e.how ?? null,
  },
  context: { playbook: $workflow.name, n8n_execution_id: $execution.id, recv_execution_id: input.recv_execution_id ?? null },
} }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a connection error, a timeout or HTTP 5xx
// -> wait and call again; anything else is passed on. Outside any loop: this
// node runs once per call, so $runIndex counts the calls. Never parks: the
// last failure goes into the result.
const r = $input.first().json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Read TheHive alert';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a connection error, a timeout or HTTP 5xx
// -> wait and call again; anything else is passed on. Outside any loop: this
// node runs once per call, so $runIndex counts the calls. Never parks: the
// last failure goes into the result.
const r = $input.first().json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'List TheHive comments';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// pb-ssh-response (C9 v0): may this approval run? Pure. In this order:
//  - ignored, no comment: an approval by n8n@asox.local itself (only an
//    analyst approves; recv-thehive-event drops those already), or the tag
//    no longer on the alert (re-read);
//  - failed, no comment: the alert or its comments couldn't be read;
//  - refused, one comment: response actions disabled (kill switch); no
//    proposal on the alert (a writeback line `- <proposal marker> <agent id>
//    <srcip> <command> <timeout>` by n8n@asox.local); a response already sent
//    for it (a `<response marker> ...: sent` or `: unknown` comment; `not
//    sent` ones don't count, so an approval can be given again after a
//    failure); the approval more than approval.window_s after the proposal
//    (the writeback comment's time). The rate cap and the other guardrails
//    are lib-wazuh-active-response's, checked again when it runs.
function decide(ctx, a, c) {
  const resp = ctx.config.response;
  const n8nUser = ctx.config.thehive.n8n_user;
  const ev = ctx.event;
  const tag = resp.approval.tag;
  const cls = (x) => (x.decision === 'error' ? (x.retry_exhausted ? 'thehive_unreachable' : (x.http_status ? `thehive_${x.http_status}` : 'thehive_error'))
    : (x.statusCode === 200 ? 'bad_answer' : `thehive_${x.statusCode}`));
  if (ev.actor === n8nUser || ev.actor === null) return { decision: 'ignore', reason: `approval by ${ev.actor ?? 'an unknown user'}: only an analyst approves, never ${n8nUser}` };
  if (a.decision !== 'response' || a.statusCode !== 200 || !Array.isArray(a.body) || a.body.length !== 1) {
    return { decision: 'failed', reason: `alert ${ev.thehive_alert_id} not read (${cls(a)})` };
  }
  const alert = a.body[0];
  const tags = Array.isArray(alert.tags) ? alert.tags : [];
  const summary = { thehive_alert_id: alert._id, wazuh_alert_id: alert.sourceRef ?? null, source: alert.source ?? null, tags };
  if (!tags.includes(tag)) return { decision: 'ignore', reason: `tag ${tag} is no longer on the alert`, alert: summary };
  if (c.decision !== 'response' || c.statusCode !== 200 || !Array.isArray(c.body)) {
    return { decision: 'failed', reason: `comments of alert ${alert._id} not read (${cls(c)})`, alert: summary };
  }
  const mine = c.body
    .filter((cm) => (cm.createdBy ?? cm._createdBy) === n8nUser && typeof cm.message === 'string')
    .map((cm) => ({ id: cm._id, at_ms: cm.createdAt ?? cm._createdAt ?? null, lines: cm.message.split('\n') }))
    .sort((x, y) => (x.at_ms ?? 0) - (y.at_ms ?? 0));
  const firstLines = mine.map((m) => m.lines[0]);
  const approvedAt = ev.event_time_ms ?? Date.now();
  const base = { alert: summary, approved_by: ev.actor, approved_at_ms: approvedAt, first_lines: firstLines };
  const refuse = (code, reason, extra = {}) => ({ decision: 'refuse', code, reason, ...base, ...extra });
  if (resp.enabled !== true) return refuse('disabled', 'response actions are disabled (lib-config response.enabled, the kill switch)');
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const wbFirst = new RegExp(`^${esc(ctx.config.writeback.marker)} wazuh-alert-id=`);
  const line = new RegExp(`^- ${esc(resp.markers.proposal)} (\\S+) (\\S+) (\\S+) (\\d+)$`);
  let proposal = null;
  for (const m of mine) {
    if (!wbFirst.test(m.lines[0])) continue;
    for (const l of m.lines) {
      const x = line.exec(l);
      if (x) proposal = { agent_id: x[1], srcip: x[2], command: x[3], timeout_s: Number(x[4]), at_ms: m.at_ms, comment_id: m.id };
    }
  }
  if (!proposal) return refuse('no-proposal', `this alert has no response proposal from n8n (pb-ssh-bruteforce proposes one in its writeback, for lib-config response.routes ${resp.routes.join(', ')})`);
  const done = mine.find((m) => m.lines[0].startsWith(`${resp.markers.response} `) && /\): (sent|unknown)\b/.test(m.lines[0]));
  if (done) {
    return refuse('already-executed', `a response was already sent for this alert (n8n comment of ${new Date(done.at_ms).toISOString()}: "${done.lines[0]}")`, { proposal });
  }
  const age = approvedAt - proposal.at_ms;
  if (!(Number.isFinite(age) && age >= 0 && age <= resp.approval.window_s * 1000)) {
    return refuse('expired', `the approval at ${new Date(approvedAt).toISOString()} is outside the ${resp.approval.window_s} s window after the proposal (${new Date(proposal.at_ms).toISOString()})`, { proposal });
  }
  return { decision: 'execute', ...base, proposal };
}

return [{ json: decide($('Context').first().json, $('Assess: Read TheHive alert').first().json, $input.first().json) }];

// The approved proposal, executed by lib-wazuh-active-response, which checks
// every guardrail again (kill switch, catalog, protected addresses, the agent
// in the group and active, agent addresses, the rate cap) and, in dry_run,
// builds the request without sending it.
const c = $('Context').first().json;
const d = $input.first().json;
return [{ json: {
  action: 'execute', command: d.proposal.command, srcip: d.proposal.srcip, agent: { id: d.proposal.agent_id },
  config: c.config, context: { ...c.context, thehive_alert_id: d.alert.thehive_alert_id },
} }];

// What follows the action. Live and sent: tag the alert
// response.done_tag_prefix + command and set the custom field
// response.containment_field (the catalog's containment_action; the object
// form of customFields, which keeps the alert's other fields: an array
// replaces them all, checked on 5.7.6), then asox-metrics (mode update):
// t_contained = Wazuh's answer time (its Date header), outcome success. Live
// and not sent or unknown: outcome failed only. dry_run, or refused by a
// guardrail: nothing (the comment says why).
const c = $('Context').first().json;
const d = $('Decide').first().json;
const r0 = $input.first().json;
// On Error = continue: an unexpected failure inside the lib arrives as {error};
// it may have sent the command, so it counts as unknown.
const r = typeof r0.status === 'string' ? r0
  : { status: 'unknown', code: 'unexpected', reason: `unexpected error in lib-wazuh-active-response: ${r0.error ?? 'no result'}`,
    mode: c.config.response.mode, line: `unknown: unexpected error in lib-wazuh-active-response (${r0.error ?? 'no result'})`, agent: null, revert: null };
const resp = c.config.response;
const live = r.mode === 'live';
const cmd = resp.commands[d.proposal.command] ?? {};
const update = live && r.status === 'sent'
  ? { addTags: [`${resp.done_tag_prefix}${d.proposal.command}`], customFields: { [resp.containment_field]: cmd.containment_action } }
  : null;
let metrics = null;
if (live && ['sent', 'not_sent', 'unknown'].includes(r.status)) {
  metrics = { mode: 'update', alert_id: d.alert.wazuh_alert_id, source: d.alert.source,
    fields: r.status === 'sent' ? { t_contained: r.answered_at, outcome: 'success' } : { outcome: 'failed' } };
}
return [{ json: { result: r, update, metrics } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a connection error, a timeout or HTTP 5xx
// -> wait and call again; anything else is passed on. Outside any loop: this
// node runs once per call, so $runIndex counts the calls. Never parks: the
// last failure goes into the result.
const r = $input.first().json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Update TheHive alert';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

// C11: lib-metrics-upsert, mode update (a missing document is skipped, never
// created; asox-test alerts have none).
return [{ json: { ...$('After the action').first().json.metrics, config: $('Context').first().json.config } }];

// The one comment this approval gets (by n8n@asox.local, on the alert):
//  - executed (any lib status but refused): first line
//    `<response marker> <command> <srcip> on <agent> (<mode>): <sent | not sent | not sent (dry_run) | unknown>`,
//    then who approved and when, the request, Wazuh's answer, the revert,
//    the TheHive and asox-metrics updates. `sent` and `unknown` block a new
//    approval of this alert (Decide);
//  - refused (Decide or the lib's guardrails): first line
//    `<refused marker> <code>`, why, nothing changed; not written again when
//    n8n already wrote that first line on this alert (a repeated tag);
//  - ignored or failed: no comment.
const c = $('Context').first().json;
const d = $('Decide').first().json;
const resp = c.config.response;
const iso = (ms) => (Number.isFinite(ms) ? new Date(ms).toISOString() : 'unknown time');
const head = [`n8n playbook **${c.context.playbook}**, execution ${c.context.n8n_execution_id}`
  + `${c.context.recv_execution_id ? ` (approval event: recv-thehive-event execution ${c.context.recv_execution_id})` : ''}.`, ''];
const by = `${d.approved_by} at ${iso(d.approved_at_ms)} with the tag ${resp.approval.tag}`
  + `${d.proposal ? ` (proposal of ${iso(d.proposal.at_ms)}; window ${resp.approval.window_s} s)` : ''}`;
const approval = `Approved by ${by}.`;
function refusal(code, reason) {
  const first = `${resp.markers.refused} ${code}`;
  if ((d.first_lines ?? []).includes(first)) return { post: false, why: `refusal ${code} already explained on this alert` };
  return { post: true, kind: 'refused', first, message: [first, '', ...head,
    `Approval by ${by}: not executed: ${reason}.`, '', 'Nothing was changed.'].join('\n') };
}
let plan;
if (d.decision === 'ignore' || d.decision === 'failed') {
  plan = { post: false, why: `${d.decision}: ${d.reason}` };
} else if (d.decision === 'refuse') {
  plan = refusal(d.code, d.reason);
} else {
  const after = $('After the action').first().json;
  const r = after.result;
  if (r.status === 'refused') {
    plan = refusal(r.code, r.reason);
  } else {
    const agentName = r.agent?.name ?? `agent ${d.proposal.agent_id}`;
    const word = { sent: 'sent', unknown: 'unknown', dry_run: 'not sent (dry_run)', not_sent: 'not sent' }[r.status] ?? r.status;
    const first = `${resp.markers.response} ${d.proposal.command} ${d.proposal.srcip} on ${agentName} (${r.mode}): ${word}`;
    // dry_run: said right under the first line (whose format is fixed).
    const dry = r.status === 'dry_run' ? ['**DRY RUN: nothing was blocked** (RESPONSE_MODE in topology.env; mode source in the Result line).', ''] : [];
    const lines = [first, '', ...dry, ...head, `- ${approval}`,
      `- Action: ${d.proposal.command} ${d.proposal.srcip} on ${agentName}${r.agent ? ` (agent ${r.agent.id})` : ''} ${r.revert?.automatic === false ? 'with NO timeout' : `for ${r.timeout_s ?? d.proposal.timeout_s} s`}, Wazuh command ${r.sent_command ?? r.api_command}.`];
    if (r.request) lines.push(`- Request: ${r.request.method} ${r.request.path} ${JSON.stringify(r.request.body)}`);
    if (r.first_api) lines.push(`- First request answered Wazuh error 1652 (${r.api_command} not defined on the manager); lib-config response.allow_no_timeout is true, so it was sent again as ${r.sent_command}.`);
    if (r.status === 'sent') {
      lines.push(`- Result: sent to ${r.agent.name} (Wazuh accepted, total_affected ${r.api.total_affected}) at ${r.answered_at}. Wazuh's answer means "sent to the agent", not "blocked": a command sent while the agent reloads (group change, restart) can be lost; the agent's active-responses.log shows the run.`);
    } else if (r.status === 'dry_run') {
      lines.push(`- Result: DRY RUN: the request was built and not sent (response.mode 'dry_run', ${resp.mode_source ?? 'lib-config'}); nothing was blocked or changed on ${agentName}. To block, set RESPONSE_MODE=live in topology.env, re-render and recreate n8n.`);
    } else {
      lines.push(`- Result: ${r.line}.`);
    }
    if (r.revert?.automatic === true) lines.push(`- Revert: automatic after ${r.revert.after_s} s${r.revert.at ? `, at about ${r.revert.at}` : ''} (the manager's <active-response> timeout).`);
    else if (r.revert?.automatic === false) lines.push(`- Revert: NO automatic revert: unblock by hand on the agent with \`${r.revert.manual}\`.`);
    if (r.status === 'sent' || r.status === 'unknown') lines.push(`- Rate cap: ${resp.rate_cap_per_hour} response action(s) per hour, all alerts together.`);
    if (after.update) {
      const u = $('Assess: Update TheHive alert').isExecuted ? $('Assess: Update TheHive alert').first().json : null;
      const okU = u && u.decision === 'response' && u.statusCode >= 200 && u.statusCode < 300;
      const what = `tag ${after.update.addTags.join(', ')} and ${resp.containment_field} ${Object.values(after.update.customFields)[0]}`;
      lines.push(okU ? `- TheHive: ${what} set on this alert.`
        : `- TheHive: ${what} not set: update failed (${u ? (u.decision === 'error' ? `${u.retry_exhausted ? 'thehive_unreachable' : 'thehive_error'} after ${u.attempts} call(s)` : `HTTP ${u.statusCode}`) : 'not attempted'}).`);
    } else {
      lines.push(`- TheHive: no tag, ${resp.containment_field} unchanged (${{ dry_run: 'dry_run', unknown: 'not confirmed' }[r.status] ?? 'nothing sent'}).`);
    }
    if (after.metrics) {
      const m = $('Metrics (lib-metrics-upsert)').isExecuted ? $('Metrics (lib-metrics-upsert)').first().json : null;
      const f = after.metrics.fields;
      lines.push(`- asox-metrics: ${f.t_contained ? `t_contained ${f.t_contained}, ` : ''}outcome ${f.outcome}: ${m && typeof m.line === 'string' ? m.line : 'metrics: failed (unexpected)'}`);
    } else {
      lines.push('- asox-metrics: not written (dry_run).');
    }
    const changed = r.status === 'sent' ? `${agentName} (firewall rule through Wazuh active response), TheHive (this comment, tag, ${resp.containment_field}), Wazuh indexer (asox-metrics)`
      : (r.status === 'unknown' ? `${agentName} possibly (no confirmed answer), TheHive (this comment), Wazuh indexer (asox-metrics)`
        : `TheHive (this comment)${after.metrics ? ', Wazuh indexer (asox-metrics)' : ''}`);
    lines.push(`- Systems changed: ${changed}.`);
    plan = { post: true, kind: 'response', first, message: lines.join('\n') };
  }
}
return [{ json: plan }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): only an error where the request never reached TheHive (a timeout may have written the comment, so it is never repeated)
// -> wait and call again; anything else is passed on. Outside any loop: this
// node runs once per call, so $runIndex counts the calls. Never parks: the
// last failure goes into the result.
const r = $input.first().json;
const policy = $('Context').first().json.config.thehive_http;
const NODE = 'Post TheHive comment';
const attempt = $runIndex + 1;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : false;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, attempts: attempt, retry_exhausted: transient, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', stage: NODE, attempts: attempt, statusCode: status, body: r.body } }];

const c = $('Context').first().json;
const d = $('Decide').first().json;
const p = $('Comment plan').first().json;
const after = $('After the action').isExecuted ? $('After the action').first().json : null;
let comment = p.post ? 'not written' : `none (${p.why})`;
if (p.post) {
  const a = $('Assess: Post TheHive comment').isExecuted ? $('Assess: Post TheHive comment').first().json : null;
  comment = a && a.decision === 'response' && a.statusCode === 201 ? `written (${p.kind}: ${p.first})`
    : `failed (${a ? (a.decision === 'error' ? a.message : `HTTP ${a.statusCode}`) : 'not attempted'})`;
}
return [{ json: {
  outcome: after ? after.result.status : d.decision === 'refuse' ? 'refused' : d.decision,
  code: after ? (after.result.code ?? null) : (d.code ?? null),
  reason: after ? (after.result.reason ?? after.result.line) : (d.reason ?? null),
  line: after ? after.result.line : null,
  thehive_alert_id: c.event.thehive_alert_id,
  wazuh_alert_id: d.alert?.wazuh_alert_id ?? null,
  approved_by: c.event.actor,
  proposal: d.proposal ?? null,
  mode: c.config.response.mode,
  comment,
  thehive_update: after?.update ? ($('Assess: Update TheHive alert').isExecuted && $('Assess: Update TheHive alert').first().json.statusCode === 204 ? 'ok' : 'failed') : null,
  metrics: after?.metrics ? ($('Metrics (lib-metrics-upsert)').isExecuted ? $('Metrics (lib-metrics-upsert)').first().json.line ?? 'metrics: failed (unexpected)' : null) : null,
  playbook: $workflow.name,
} }];
